#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Purpose: put the free review layers on this public repository
# (docs/research/free-tier-code-review-public-repo.md): CodeQL default setup,
# the Sourcery and CodeRabbit GitHub Apps with their quiet settings, and a
# first trigger on an open PR to see whether a comment from `vmb-agent`
# starts a review.
#
# Run it from anywhere:  ./scripts/setup-review-apps.sh
# Safe to re-run: every stage checks or asks before it changes anything.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5

# Always operate on the repo, no matter where the script was launched from.
cd "$(git rev-parse --show-toplevel)"

REPO=ubeann/vmb

# The default gh account is the agents' (vmb-agent, a collaborator). Repo
# settings need the owner's token, so take it from the owner's gh login when
# one exists and fall back to whatever gh has.
owner_gh() {
  local token
  if token=$(gh auth token --user ubeann 2>/dev/null) && [[ -n "$token" ]]; then
    GH_TOKEN="$token" gh "$@"
  else
    gh "$@"
  fi
}

banner "VMB: free code review layers on the public repository"

# ── Stage 1: CodeQL default setup ─────────────────────────────────────────
stage "GitHub: CodeQL default setup"
say "Code scanning is free on a public repository and posts check annotations, not PR comments."
state=$(owner_gh api "repos/$REPO/code-scanning/default-setup" --jq .state 2>/dev/null || echo unknown)
if [[ "$state" == "configured" ]]; then
  say "Already configured; nothing to do."
elif confirm "Code scanning is '$state'. Enable the default setup now?"; then
  if owner_gh api -X PATCH "repos/$REPO/code-scanning/default-setup" \
    -f state=configured -f query_suite=default >/dev/null; then
    printf '  %s✓ enabled%s CodeQL default setup; the first scan is running\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("Enable CodeQL default setup: Settings → Code security → Code scanning")
    warn "could not enable it with this token; do it in the browser."
    open_url "https://github.com/$REPO/settings/security_analysis"
  fi
else
  SKIPPED+=("Enable CodeQL default setup")
fi
sec=$(owner_gh api "repos/$REPO" --jq '.security_and_analysis | "secret scanning \(.secret_scanning.status), push protection \(.secret_scanning_push_protection.status)"' 2>/dev/null || true)
[[ -n "$sec" ]] && note "$sec (both default to enabled on a public repository)"

# ── Stage 2: Sourcery app ─────────────────────────────────────────────────
stage "Sourcery: install the GitHub App on vmb only"
say "Sourcery's Open Source plan is free for public repositories: automatic reviews,"
say "drafts skipped by default, 250k diff characters per developer per 7 days."
open_url "https://github.com/apps/sourcery-ai/installations/new"
step "Pick the 'ubeann' account."
step "Choose 'Only select repositories' and select 'vmb'. Install."
step "If Sourcery asks you to sign in, use the same GitHub account."
pause "Press Enter once the app is installed."

# ── Stage 3: Sourcery settings ────────────────────────────────────────────
stage "Sourcery: quiet review settings for vmb"
say "Sourcery keeps its settings in its dashboard, not in a repo file."
open_url "https://app.sourcery.ai/"
step "Open the 'vmb' repository and turn 'Use Organization Settings' off."
step "Review profile: Quiet. Review draft pull requests: off (the default)."
step "Pull request summary, Review guide, Sequence diagrams, Tips and commands: all off."
step "AI review comments: on."
step "Path filters: pnpm-lock.yaml, **/*.snap, **/generated/**, docs/**."
step "Ignore pull requests whose title contains: WIP."
note "Add review rules from CODING_STANDARDS.md only after a week of reading its findings."
pause "Press Enter once the settings are saved."

# ── Stage 4: CodeRabbit app ───────────────────────────────────────────────
stage "CodeRabbit: install the GitHub App on vmb only"
say "The Open Source plan gives Team features on public repositories, no card needed."
say "Below 10 stars every review is on request; .coderabbit.yaml keeps it that way."
open_url "https://github.com/apps/coderabbitai/installations/new"
step "Pick the 'ubeann' account, 'Only select repositories', select 'vmb'. Install."
step "Sign in at app.coderabbit.ai with GitHub; check the subscription page shows the Open Source plan for vmb."
step "Leave the dashboard review settings alone: .coderabbit.yaml in the repository overrides them."
pause "Press Enter once the app is installed."

# ── Stage 5: first trigger from the agent account ─────────────────────────
stage "Try both reviewers on an open PR"
say "The build posts the trigger comments as vmb-agent, so this stage posts them"
say "the same way and you watch whether each bot answers."
if ! gh pr list --repo "$REPO" --state open --limit 10 --json number,title,isDraft \
  --jq '.[] | "  #\(.number)\(if .isDraft then " (draft)" else "" end) \(.title)"'; then
  warn "could not list PRs; open one and come back."
fi
ask PR_NUMBER "PR number to try (Enter to skip):"
if [[ -n "${PR_NUMBER:-}" ]]; then
  gh pr comment "$PR_NUMBER" --repo "$REPO" --body "@sourcery-ai review" >/dev/null &&
    printf '  %s✓ posted%s @sourcery-ai review on #%s\n' "$GREEN" "$RESET" "$PR_NUMBER"
  gh pr comment "$PR_NUMBER" --repo "$REPO" --body "@coderabbitai review" >/dev/null &&
    printf '  %s✓ posted%s @coderabbitai review on #%s\n' "$GREEN" "$RESET" "$PR_NUMBER"
  open_url "https://github.com/$REPO/pull/$PR_NUMBER"
  step "Wait a few minutes. A review, or a 'rate limit' reply, from each bot means a vmb-agent comment works."
  step "No reply from a bot: post the same comment from your own account, and note it in"
  step "docs/agents/ticket-loop.md so the build asks the owner instead."
  note "@coderabbitai rate limit shows the remaining allowance without spending a review."
  pause "Press Enter when you have seen the result."
else
  SKIPPED+=("Trigger @sourcery-ai review and @coderabbitai review on a PR as vmb-agent and record whether they answer")
fi

finish
say "Next: once a week of PRs has gone through, decide whether the two reviewers join"
say "the Review table in docs/agents/model-routing.md (research note: review by 2026-11-18)."
